// frontend/src/lib/mfa.ts

/**
 * MFA Manager (Frontend Utility)
 *
 * SECURITY NOTES:
 * - TOTP Secret Generation and Verification are handled ENTIRELY by the backend.
 * - This file ONLY handles formatting data for display.
 * - REAL backup codes are generated by the backend (mfa-setup-verify) using
 *   crypto.randomBytes. Codes generated here are NEVER valid for authentication.
 */

/** RFC 4648 base32 alphabet: A-Z and 2-7, with optional padding. */
const BASE32_REGEX = /^[A-Z2-7]+={0,6}$/;

export class MFAManager {
  /**
   * Formats a backend-provided secret into a standard OTPAuth URI for QR code
   * generation.
   *
   * ✅ FIXED: previously stripped non-base32 characters via .replace(), which
   * SILENTLY SHORTENED the secret — a secret containing any of 0/1/8/9 became
   * a weaker key that would fail verification with no visible error. We now
   * REJECT invalid input instead of mutating it.
   *
   * @param secret - The base32 secret string from the backend (mfa-setup-init)
   * @param email - The user's email address (used as the account label)
   * @param issuer - The name of your application
   * @returns A valid otpauth:// URL compatible with Google Authenticator, Authy, etc.
   */
  static formatQRUrl(secret: string, email: string, issuer: string = "SecureWebProduct"): string {
    if (!secret || typeof secret !== 'string') {
      throw new Error('Invalid secret provided');
    }

    if (!email || typeof email !== 'string') {
      throw new Error('Invalid email provided');
    }

    // ✅ FIXED: validate — do NOT mutate. A mutated secret is a corrupt key.
    const normalizedSecret = secret.trim().toUpperCase();
    if (!BASE32_REGEX.test(normalizedSecret)) {
      throw new Error('Invalid secret format');
    }

    // Whitelist-sanitize email and issuer for URI safety
    const safeEmail = email.replace(/[^a-zA-Z0-9@.+-]/g, '');
    const safeIssuer = issuer.replace(/[^a-zA-Z0-9\s-]/g, '');

    if (!safeEmail) {
      throw new Error('Invalid email format');
    }

    const label = encodeURIComponent(safeEmail);
    const encodedIssuer = encodeURIComponent(safeIssuer);

    return `otpauth://totp/${encodedIssuer}:${label}?secret=${normalizedSecret}&issuer=${encodedIssuer}&algorithm=SHA1&digits=6&period=30`;
  }

  /**
   * ⚠️ PLACEHOLDER ONLY — NEVER USE FOR AUTHENTICATION.
   *
   * Generates random strings for UI demonstration only. The REAL backup codes
   * come from the backend (mfa-setup-verify) and are hashed with Argon2
   * server-side. Codes from this function authenticate nothing.
   *
   * @param count - Number of codes to generate
   * @param length - Length of each code
   * @returns Array of random strings (NOT valid auth codes)
   */
  static generatePlaceholderCodes(count: number = 10, length: number = 12): string[] {
    // ✅ FIXED: guard against SSR/prerender environments where `window` is
    // undefined — importing this module in a Next.js/SSG pass previously
    // crashed with "window is not defined".
    if (typeof window === 'undefined' || !window.crypto?.getRandomValues) {
      throw new Error('[MFAManager] Web Crypto API unavailable (SSR or insecure context).');
    }

    const codes: string[] = [];
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

    const array = new Uint32Array(length * count);
    window.crypto.getRandomValues(array);

    let arrayIndex = 0;
    for (let i = 0; i < count; i++) {
      let code = '';
      for (let j = 0; j < length; j++) {
        code += chars[array[arrayIndex++] % chars.length];
      }
      codes.push(code);
    }

    return codes;
  }

  /**
   * Validates the FORMAT of a backup code entered by the user.
   * Does NOT verify against the database (the backend does that).
   *
   * @param code - The code entered by the user
   * @returns true if format is valid (12 alphanumeric characters)
   */
  static isValidFormat(code: string): boolean {
    return /^[A-Z0-9]{12}$/i.test(code);
  }
}
